<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Dezerx; use Throwable; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Http\JsonResponse; use Illuminate\Support\Facades\Crypt; use Pterodactyl\Services\Dezerx\Ai\Ai; use Illuminate\Support\Facades\Session; use Pterodactyl\Services\Dezerx\Ai\Runs; use Pterodactyl\Services\Dezerx\Ai\Stopped; use Pterodactyl\Services\Dezerx\Ai\Assistant; use Pterodactyl\Services\Dezerx\Ai\ModelCatalog; use Pterodactyl\Services\Dezerx\Ai\AiUnavailable; use Symfony\Component\HttpFoundation\StreamedResponse; use Pterodactyl\Http\Requests\Api\Client\ClientApiRequest; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; class AiController extends ClientApiController { private const MAX_TURNS = 80; private const MAX_CHARS = 200000; private const HEARTBEAT = 10; private float $lastEmit = 0.0; public function __construct(private Assistant $assistant) { parent::__construct(); } public function chat(ClientApiRequest $request): StreamedResponse|JsonResponse { if (!Ai::enabled()) { return new JsonResponse(['message' => 'The assistant is turned off.'], 404); } $data = $request->validate([ 'run' => ['sometimes', 'string', 'max:64'], 'server' => ['sometimes', 'nullable', 'string', 'max:64'], 'messages' => ['required', 'array', 'min:1', 'max:' . self::MAX_TURNS], 'messages.*.role' => ['required', 'string', 'in:user,assistant'], 'messages.*.content' => ['present', 'nullable', 'string', 'max:' . self::MAX_CHARS], 'approve' => ['sometimes', 'array', 'max:20'], 'approve.*' => ['string', 'max:32'], ]); $user = $request->user(); if ($this->assistant->credential($user) === null) { return new JsonResponse(['message' => Ai::keyMode() === 'panel' ? 'No API key has been set for this panel yet.' : 'Add your own API key to use the assistant.', 'needsKey' => Ai::keyMode() !== 'panel'], 409); } $messages = Assistant::normalise(array_values($data['messages'])); if ($messages === []) { return new JsonResponse(['message' => 'There is nothing to answer yet.'], 422); } $run = (string) ($data['run'] ?? Str::uuid()); Runs::begin($run, $user); $seconds = Ai::timeBudget() + 120; $slot = Runs::slot($seconds); if ($slot === null) { usleep(1500000); $slot = Runs::slot($seconds); } if ($slot === null) { Runs::forget($run, $user); return new JsonResponse(['message' => 'The assistant is answering as many questions as this panel allows at once. Try again in a minute.'], 503); } if (!Runs::claim($user)) { $slot->release(); Runs::forget($run, $user); $allowance = Runs::allowance($user); return new JsonResponse(['message' => 'You have asked every question this panel allows for now. Your allowance comes back in ' . $allowance['resetsIn'] . ' seconds.', 'allowance' => $allowance], 429); } $approve = array_values($data['approve'] ?? []); $hooks = [ 'onStep' => function (array $steps) { $this->emit(['type' => 'step', 'step' => end($steps) ?: null]); }, 'onTick' => function () { if (microtime(true) - $this->lastEmit >= self::HEARTBEAT) { $this->emit(['type' => 'ping']); } }, 'shouldStop' => fn () => connection_aborted() === 1 || Runs::stopping($run, $user), 'ip' => $request->ip(), 'here' => $data['server'] ?? null, ]; if ($request->hasSession()) { Session::save(); } $response = new StreamedResponse(function () use ($user, $run, $messages, $approve, $hooks, $slot, $seconds) { set_time_limit($seconds + 60); ignore_user_abort(true); register_shutdown_function(static function () use ($slot) { $slot->release(); }); try { $this->emit(['type' => 'open', 'run' => $run]); $reply = $this->assistant->answer($user, $messages, $approve, $hooks); } catch (Stopped) { $this->emit(['type' => 'stopped']); return; } catch (AiUnavailable $e) { $this->emit(['type' => 'error', 'message' => $e->getMessage()]); return; } catch (Throwable $e) { report($e); $this->emit(['type' => 'error', 'message' => 'Something went wrong answering that. An administrator has the details.']); return; } finally { $slot->release(); Runs::forget($run, $user); } $this->emit(['type' => 'done', 'text' => $reply->text, 'steps' => $reply->steps, 'truncated' => $reply->truncated, 'pending' => $reply->pending, 'allowance' => Runs::allowance($user)]); }); $response->headers->set('Content-Type', 'application/x-ndjson'); $response->headers->set('Cache-Control', 'no-cache, no-store, no-transform'); $response->headers->set('X-Accel-Buffering', 'no'); return $response; } public function stop(ClientApiRequest $request, string $run): JsonResponse { Runs::stop($run, $request->user()); return new JsonResponse(['stopping' => true]); } public function key(ClientApiRequest $request): JsonResponse { if (!Ai::enabled() || Ai::keyMode() === 'panel') { return new JsonResponse(['message' => 'This panel does not take your own key.'], 403); } $data = $request->validate(['key' => ['nullable', 'string', 'max:400'], 'own' => ['sometimes', 'boolean'], 'provider' => ['sometimes', 'string'], 'model' => ['sometimes', 'nullable', 'string', 'max:120'], 'remove' => ['sometimes', 'boolean']]); $user = $request->user(); if ($data['remove'] ?? false) { Ai::setPreferences($user, ['key' => null, 'provider' => null, 'model' => null, 'own' => false]); return new JsonResponse(['saved' => true, 'hasOwnKey' => false, 'own' => false, 'provider' => null, 'model' => null]); } $key = trim((string) ($data['key'] ?? '')); $held = Ai::userKey($user) !== null; $provider = in_array($data['provider'] ?? '', Ai::userProviders(), true) ? (string) $data['provider'] : Ai::provider(); $model = trim((string) ($data['model'] ?? '')); $preferences = ['provider' => $provider, 'model' => $model !== '' ? $model : null, 'own' => (bool) ($data['own'] ?? true)]; if ($key !== '') { $preferences['key'] = Crypt::encryptString($key); } Ai::setPreferences($user, $preferences); return new JsonResponse(['saved' => true, 'hasOwnKey' => $key !== '' || $held, 'own' => Ai::prefersOwnKey($user), 'provider' => $provider, 'model' => $model !== '' ? $model : null]); } public function models(ClientApiRequest $request, ModelCatalog $catalog): JsonResponse { if (!Ai::enabled()) { return new JsonResponse(['message' => 'The assistant is turned off.'], 404); } $data = $request->validate(['provider' => ['required', 'string'], 'key' => ['sometimes', 'nullable', 'string', 'max:400'], 'fresh' => ['sometimes', 'boolean']]); $provider = Ai::sanitiseProvider($data['provider']); if ($provider === null) { return new JsonResponse(['message' => 'No such service.'], 422); } $user = $request->user(); $key = trim((string) ($data['key'] ?? '')); $key = $key !== '' ? $key : (Ai::userProvider($user) === $provider ? Ai::userKey($user) : null) ?? Ai::panelKey($provider); return new JsonResponse([...$catalog->for($provider, $key, (bool) ($data['fresh'] ?? false)), 'hasKey' => $key !== null && $key !== '']); } public function mode(ClientApiRequest $request): JsonResponse { if (!Ai::enabled()) { return new JsonResponse(['message' => 'The assistant is turned off.'], 404); } $data = $request->validate(['askFirst' => ['required', 'boolean']]); Ai::setPreferences($request->user(), ['askFirst' => (bool) $data['askFirst']]); return new JsonResponse(['askFirst' => (bool) $data['askFirst']]); } public function allowance(Request $request): JsonResponse { return new JsonResponse(['allowance' => Runs::allowance($request->user())]); } private function emit(array $payload): void { $this->lastEmit = microtime(true); echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE) . "\n"; while (ob_get_level() > 0) { ob_end_flush(); } flush(); } } 